-- ============================================================
SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;
CREATE DATABASE IF NOT EXISTS new_063 DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci;
USE new_063;

DROP TABLE IF EXISTS `book`;
DROP TABLE IF EXISTS `book_category`;
DROP TABLE IF EXISTS `stock_in`;
DROP TABLE IF EXISTS `stock_flow`;
DROP TABLE IF EXISTS `book_order`;
DROP TABLE IF EXISTS `book_review`;
DROP TABLE IF EXISTS `book_return`;
DROP TABLE IF EXISTS `replenish_plan`;
DROP TABLE IF EXISTS `replenish_rule`;
DROP TABLE IF EXISTS `review_useful`;
DROP TABLE IF EXISTS `sys_user`;
DROP TABLE IF EXISTS `sys_org`;
