-- book 图书
CREATE TABLE `book` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `book_no` varchar(32) NOT NULL DEFAULT '' COMMENT '图书编号 BK+yyMMdd+4位序号',
  `isbn` varchar(20) NOT NULL DEFAULT '' COMMENT 'ISBN 13位数字，允许带连字符',
  `book_name` varchar(120) NOT NULL DEFAULT '' COMMENT '书名 2至80字',
  `sub_title` varchar(120) NULL DEFAULT NULL COMMENT '副标题',
  `author` varchar(80) NOT NULL DEFAULT '' COMMENT '作者，多作者用顿号分隔',
  `publisher` varchar(80) NOT NULL DEFAULT '' COMMENT '出版社',
  `category_id` bigint NOT NULL DEFAULT '0' COMMENT '分类 book_category.id（二级分类）',
  `list_price` decimal(10,2) NOT NULL DEFAULT '0' COMMENT '定价',
  `sale_price` decimal(10,2) NOT NULL DEFAULT '0' COMMENT '售价，不得高于定价1.2倍',
  `publish_date` date NULL DEFAULT NULL COMMENT '出版日期',
  `edition` varchar(20) NOT NULL DEFAULT '' COMMENT '版次',
  `status` varchar(20) NOT NULL DEFAULT '' COMMENT '待上架/在售/缺货/已下架/停售',
  `stock_qty` int NOT NULL DEFAULT '0' COMMENT '可售库存（文档补充字段）',
  `locked_qty` int NOT NULL DEFAULT '0' COMMENT '下单锁定库存（文档补充字段）',
  `total_sales` int NOT NULL DEFAULT '0' COMMENT '累计销量（已签收计入）',
  `shortage_count` int NOT NULL DEFAULT '0' COMMENT '近90天缺货次数（创新点因子）',
  `cover_image` varchar(200) NULL DEFAULT NULL COMMENT '封面图相对路径',
  `summary` varchar(500) NULL DEFAULT NULL COMMENT '内容摘要/目录，详情页展示',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '逻辑删除 0 否 1 是',
  `create_by` bigint NULL DEFAULT NULL COMMENT '创建人',
  `update_by` bigint NULL DEFAULT NULL COMMENT '最后修改人',
  `version` int NOT NULL DEFAULT '0' COMMENT '乐观锁版本号',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_book_book_no` (`book_no`),
  KEY `idx_book_category_id_status` (`category_id`,`status`),
  KEY `idx_book_publisher` (`publisher`),
  KEY `idx_book_book_name` (`book_name`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='图书';

-- book_category 图书分类
CREATE TABLE `book_category` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `category_code` varchar(30) NOT NULL DEFAULT '' COMMENT '分类编码，大写字母与数字',
  `category_name` varchar(50) NOT NULL DEFAULT '' COMMENT '分类名称，同级不可重名',
  `parent_id` bigint NOT NULL DEFAULT '0' COMMENT '父分类，0 表示一级分类',
  `sort_no` int NOT NULL DEFAULT '0' COMMENT '排序号，越小越靠前',
  `is_home` tinyint NOT NULL DEFAULT '0' COMMENT '0否 1是，首页推荐位',
  `description` varchar(200) NULL DEFAULT NULL COMMENT '分类说明',
  `book_count` int NOT NULL DEFAULT '0' COMMENT '关联图书数量',
  `status` tinyint NOT NULL DEFAULT '0' COMMENT '1启用 0停用',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '逻辑删除 0 否 1 是',
  `create_by` bigint NULL DEFAULT NULL COMMENT '创建人',
  `update_by` bigint NULL DEFAULT NULL COMMENT '最后修改人',
  `version` int NOT NULL DEFAULT '0' COMMENT '乐观锁版本号',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_book_category_category_code` (`category_code`),
  KEY `idx_book_category_parent_id_sort_no` (`parent_id`,`sort_no`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='图书分类';

-- stock_in 入库单
CREATE TABLE `stock_in` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `stock_in_no` varchar(32) NOT NULL DEFAULT '' COMMENT '入库单号 RK+yyMMdd+4位序号',
  `book_id` bigint NOT NULL DEFAULT '0' COMMENT '图书 book.id',
  `supplier_name` varchar(80) NOT NULL DEFAULT '' COMMENT '供货书商',
  `in_qty` int NOT NULL DEFAULT '0' COMMENT '入库数量 1至5000',
  `purchase_price` decimal(10,2) NOT NULL DEFAULT '0' COMMENT '采购单价',
  `batch_no` varchar(30) NOT NULL DEFAULT '' COMMENT '批次号 图书ID后4位+yyMMdd',
  `quality_result` varchar(20) NOT NULL DEFAULT '' COMMENT '合格/破损/缺页/错版/待检',
  `keeper_id` bigint NOT NULL DEFAULT '0' COMMENT '质检库管员 sys_user.id',
  `in_time` datetime NULL DEFAULT NULL COMMENT '质检合格入库时间',
  `status` varchar(20) NOT NULL DEFAULT '' COMMENT '待质检/已入库/已退回/已作废',
  `remark` varchar(200) NULL DEFAULT NULL COMMENT '质检说明与退回原因',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '逻辑删除 0 否 1 是',
  `create_by` bigint NULL DEFAULT NULL COMMENT '创建人',
  `update_by` bigint NULL DEFAULT NULL COMMENT '最后修改人',
  `version` int NOT NULL DEFAULT '0' COMMENT '乐观锁版本号',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_stock_in_stock_in_no` (`stock_in_no`),
  KEY `idx_stock_in_book_id_status` (`book_id`,`status`),
  KEY `idx_stock_in_batch_no` (`batch_no`),
  KEY `idx_stock_in_keeper_id` (`keeper_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='入库单';

-- stock_flow 库存变动流水
CREATE TABLE `stock_flow` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `flow_no` varchar(32) NOT NULL DEFAULT '' COMMENT '流水号 KC+yyMMdd+6位序号',
  `book_id` bigint NOT NULL DEFAULT '0' COMMENT '图书 book.id',
  `change_type` varchar(20) NOT NULL DEFAULT '' COMMENT '入库/销售出库/退货入库/盘盈/盘亏/报损',
  `change_qty` int NOT NULL DEFAULT '0' COMMENT '正数增加、负数减少，不得为0',
  `before_qty` int NOT NULL DEFAULT '0' COMMENT '变动前库存',
  `after_qty` int NOT NULL DEFAULT '0' COMMENT '变动后库存=变动前+变动数量',
  `biz_no` varchar(32) NULL DEFAULT NULL COMMENT '关联入库单号或订单号',
  `operator_id` bigint NOT NULL DEFAULT '0' COMMENT '操作人 sys_user.id',
  `remark` varchar(200) NULL DEFAULT NULL COMMENT '盘亏与报损必填原因',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '逻辑删除 0 否 1 是',
  `create_by` bigint NULL DEFAULT NULL COMMENT '创建人',
  `update_by` bigint NULL DEFAULT NULL COMMENT '最后修改人',
  `version` int NOT NULL DEFAULT '0' COMMENT '乐观锁版本号',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_stock_flow_flow_no` (`flow_no`),
  KEY `idx_stock_flow_book_id_create_time` (`book_id`,`create_time`),
  KEY `idx_stock_flow_biz_no` (`biz_no`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='库存变动流水';

-- book_order 图书订单
CREATE TABLE `book_order` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `order_no` varchar(32) NOT NULL DEFAULT '' COMMENT '订单号 BO+yyMMdd+6位序号',
  `customer_id` bigint NOT NULL DEFAULT '0' COMMENT '读者 sys_user.id',
  `book_id` bigint NOT NULL DEFAULT '0' COMMENT '图书 book.id（文档补充字段）',
  `book_name` varchar(120) NOT NULL DEFAULT '' COMMENT '图书名称快照',
  `unit_price` decimal(10,2) NOT NULL DEFAULT '0' COMMENT '成交单价快照',
  `item_count` int NOT NULL DEFAULT '0' COMMENT '购买件数 1至50',
  `book_amount` decimal(10,2) NOT NULL DEFAULT '0' COMMENT '售价乘数量合计',
  `freight` decimal(10,2) NOT NULL DEFAULT '0' COMMENT '满99免运费，否则6.00',
  `discount_amount` decimal(10,2) NOT NULL DEFAULT '0' COMMENT '优惠金额，不超过图书金额50%',
  `pay_amount` decimal(10,2) NOT NULL DEFAULT '0' COMMENT '图书金额加运费减优惠',
  `receiver_name` varchar(30) NOT NULL DEFAULT '' COMMENT '收货人',
  `receiver_phone` varchar(20) NOT NULL DEFAULT '' COMMENT '收货电话，前台脱敏',
  `address_desc` varchar(200) NOT NULL DEFAULT '' COMMENT '收货地址文字描述',
  `express_company` varchar(40) NOT NULL DEFAULT '' COMMENT '快递公司（文档补充字段）',
  `express_no` varchar(64) NULL DEFAULT NULL COMMENT '物流单号',
  `pay_time` datetime NULL DEFAULT NULL COMMENT '支付时间（文档补充字段）',
  `deliver_time` datetime NULL DEFAULT NULL COMMENT '发货时间（文档补充字段）',
  `sign_time` datetime NULL DEFAULT NULL COMMENT '签收时间（文档补充字段）',
  `logistics_time` datetime NULL DEFAULT NULL COMMENT '最近物流节点时间（文档补充字段）',
  `cancel_reason` varchar(200) NULL DEFAULT NULL COMMENT '取消原因',
  `status` varchar(20) NOT NULL DEFAULT '' COMMENT '待支付/待发货/已发货/已签收/已完成/退换中/已取消',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '逻辑删除 0 否 1 是',
  `create_by` bigint NULL DEFAULT NULL COMMENT '创建人',
  `update_by` bigint NULL DEFAULT NULL COMMENT '最后修改人',
  `version` int NOT NULL DEFAULT '0' COMMENT '乐观锁版本号',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_book_order_order_no` (`order_no`),
  KEY `idx_book_order_customer_id_status` (`customer_id`,`status`),
  KEY `idx_book_order_status_create_time` (`status`,`create_time`),
  KEY `idx_book_order_book_id` (`book_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='图书订单';

-- book_review 图书书评
CREATE TABLE `book_review` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `review_no` varchar(32) NOT NULL DEFAULT '' COMMENT '书评编号 SP+yyMMdd+6位序号',
  `book_id` bigint NOT NULL DEFAULT '0' COMMENT '图书 book.id',
  `order_id` bigint NOT NULL DEFAULT '0' COMMENT '订单 book_order.id，须已签收',
  `customer_id` bigint NOT NULL DEFAULT '0' COMMENT '读者 sys_user.id',
  `score` tinyint NOT NULL DEFAULT '0' COMMENT '评分 1至5星',
  `title` varchar(60) NULL DEFAULT NULL COMMENT '书评标题',
  `content` varchar(1000) NOT NULL DEFAULT '' COMMENT '书评内容，不少于15字',
  `image_urls` varchar(1000) NULL DEFAULT NULL COMMENT '晒图相对路径，最多9张，逗号分隔',
  `useful_count` int NOT NULL DEFAULT '0' COMMENT '有用数',
  `reply_content` varchar(500) NULL DEFAULT NULL COMMENT '店员回复，仅一条',
  `reply_time` datetime NULL DEFAULT NULL COMMENT '回复时间（文档补充字段）',
  `status` varchar(20) NOT NULL DEFAULT '' COMMENT '待审核/已展示/已隐藏/已屏蔽',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '逻辑删除 0 否 1 是',
  `create_by` bigint NULL DEFAULT NULL COMMENT '创建人',
  `update_by` bigint NULL DEFAULT NULL COMMENT '最后修改人',
  `version` int NOT NULL DEFAULT '0' COMMENT '乐观锁版本号',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_book_review_review_no` (`review_no`),
  KEY `idx_book_review_order_id_book_id` (`order_id`,`book_id`),
  KEY `idx_book_review_book_id_status` (`book_id`,`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='图书书评';

-- book_return 退换单
CREATE TABLE `book_return` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `return_no` varchar(32) NOT NULL DEFAULT '' COMMENT '退换单号 TH+yyMMdd+4位序号',
  `order_id` bigint NOT NULL DEFAULT '0' COMMENT '订单 book_order.id',
  `book_id` bigint NOT NULL DEFAULT '0' COMMENT '图书 book.id，须属于该订单',
  `return_type` varchar(20) NOT NULL DEFAULT '' COMMENT '退货退款/换货/仅退款',
  `apply_qty` int NOT NULL DEFAULT '0' COMMENT '申请数量 1至购买件数',
  `refund_amount` decimal(10,2) NOT NULL DEFAULT '0' COMMENT '退款金额，不超过明细实付',
  `reason_type` varchar(20) NOT NULL DEFAULT '' COMMENT '质量问题/错发漏发/不喜欢/物流破损',
  `description` varchar(300) NOT NULL DEFAULT '' COMMENT '问题描述，不少于10字',
  `inspect_result` varchar(20) NOT NULL DEFAULT '' COMMENT '完好/缺页污损/非本店图书/待质检',
  `back_express_no` varchar(64) NULL DEFAULT NULL COMMENT '读者寄回物流单号',
  `audit_note` varchar(200) NULL DEFAULT NULL COMMENT '审核意见（文档补充字段）',
  `audit_time` datetime NULL DEFAULT NULL COMMENT '审核时间（文档补充字段）',
  `refund_time` datetime NULL DEFAULT NULL COMMENT '退款完成时间（文档补充字段）',
  `status` varchar(20) NOT NULL DEFAULT '' COMMENT '待审核/待寄回/已寄回/已退款/已驳回/已关闭',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '逻辑删除 0 否 1 是',
  `create_by` bigint NULL DEFAULT NULL COMMENT '创建人',
  `update_by` bigint NULL DEFAULT NULL COMMENT '最后修改人',
  `version` int NOT NULL DEFAULT '0' COMMENT '乐观锁版本号',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_book_return_return_no` (`return_no`),
  KEY `idx_book_return_order_id_status` (`order_id`,`status`),
  KEY `idx_book_return_book_id_status` (`book_id`,`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='退换单';

-- replenish_plan 补货建议单
CREATE TABLE `replenish_plan` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `plan_no` varchar(32) NOT NULL DEFAULT '' COMMENT '建议编号 BH+yyMMdd+4位序号',
  `book_id` bigint NOT NULL DEFAULT '0' COMMENT '图书 book.id',
  `sales_30d` int NOT NULL DEFAULT '0' COMMENT '近30天销量',
  `stock_qty` int NOT NULL DEFAULT '0' COMMENT '当前可售库存快照',
  `onway_qty` int NOT NULL DEFAULT '0' COMMENT '在途数量',
  `turnover_days` decimal(5,1) NOT NULL DEFAULT '0' COMMENT '周转天数，无销量记999',
  `season_factor` decimal(3,2) NOT NULL DEFAULT '0' COMMENT '季节与开学系数 0.80至1.50',
  `suggest_qty` int NOT NULL DEFAULT '0' COMMENT '建议补货量（公式取整）',
  `sales_level` varchar(20) NOT NULL DEFAULT '' COMMENT '畅销/平销/滞销/断销',
  `adopt_status` varchar(20) NOT NULL DEFAULT '' COMMENT '未采纳/已采纳/已忽略',
  `handler_id` bigint NULL DEFAULT NULL COMMENT '采纳或忽略操作人',
  `avg_daily` decimal(6,2) NOT NULL DEFAULT '0' COMMENT '日均销量（文档补充字段）',
  `s_sales` decimal(5,1) NOT NULL DEFAULT '0' COMMENT '近30天销量得分（文档补充字段）',
  `s_turnover` decimal(5,1) NOT NULL DEFAULT '0' COMMENT '周转天数得分（文档补充字段）',
  `s_onway` decimal(5,1) NOT NULL DEFAULT '0' COMMENT '在途数量得分（文档补充字段）',
  `s_season` decimal(5,1) NOT NULL DEFAULT '0' COMMENT '季节系数得分（文档补充字段）',
  `s_stockout` decimal(5,1) NOT NULL DEFAULT '0' COMMENT '缺货次数得分（文档补充字段）',
  `total_score` decimal(5,1) NOT NULL DEFAULT '0' COMMENT '补货优先级分（文档补充字段）',
  `origin_level` varchar(20) NOT NULL DEFAULT '' COMMENT '规则原始等级（文档补充字段）',
  `level_desc` varchar(300) NOT NULL DEFAULT '' COMMENT '结果解释：主要影响因素与未满足条件',
  `manual_qty` int NULL DEFAULT NULL COMMENT '人工修正建议量（文档补充字段）',
  `manual_note` varchar(200) NULL DEFAULT NULL COMMENT '人工修正原因，不少于5字',
  `rule_version` varchar(20) NOT NULL DEFAULT '' COMMENT '计算所用规则版本',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '逻辑删除 0 否 1 是',
  `create_by` bigint NULL DEFAULT NULL COMMENT '创建人',
  `update_by` bigint NULL DEFAULT NULL COMMENT '最后修改人',
  `version` int NOT NULL DEFAULT '0' COMMENT '乐观锁版本号',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_replenish_plan_plan_no` (`plan_no`),
  KEY `idx_replenish_plan_book_id_create_time` (`book_id`,`create_time`),
  KEY `idx_replenish_plan_sales_level_adopt_status` (`sales_level`,`adopt_status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='补货建议单';

-- replenish_rule 补货规则配置
CREATE TABLE `replenish_rule` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `rule_code` varchar(30) NOT NULL DEFAULT '' COMMENT '规则编码',
  `rule_name` varchar(60) NOT NULL DEFAULT '' COMMENT '规则名称',
  `rule_version` varchar(20) NOT NULL DEFAULT '' COMMENT '版本号 v1/v2…',
  `w_sales` decimal(5,2) NOT NULL DEFAULT '0' COMMENT '近30天销量权重',
  `w_turnover` decimal(5,2) NOT NULL DEFAULT '0' COMMENT '库存周转天数权重',
  `w_onway` decimal(5,2) NOT NULL DEFAULT '0' COMMENT '在途数量权重',
  `w_season` decimal(5,2) NOT NULL DEFAULT '0' COMMENT '季节系数权重',
  `w_stockout` decimal(5,2) NOT NULL DEFAULT '0' COMMENT '近90天缺货权重',
  `hot_line` decimal(5,1) NOT NULL DEFAULT '0' COMMENT '畅销线，默认80',
  `normal_line` decimal(5,1) NOT NULL DEFAULT '0' COMMENT '平销线，默认55',
  `safety_hot` int NOT NULL DEFAULT '0' COMMENT '畅销安全天数，默认15',
  `safety_normal` int NOT NULL DEFAULT '0' COMMENT '平销安全天数，默认7',
  `status` tinyint NOT NULL DEFAULT '0' COMMENT '1启用 0停用',
  `effective_time` datetime NULL DEFAULT NULL COMMENT '生效时间',
  `remark` varchar(200) NULL DEFAULT NULL COMMENT '变更说明',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '逻辑删除 0 否 1 是',
  `create_by` bigint NULL DEFAULT NULL COMMENT '创建人',
  `update_by` bigint NULL DEFAULT NULL COMMENT '最后修改人',
  `version` int NOT NULL DEFAULT '0' COMMENT '乐观锁版本号',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_replenish_rule_rule_code_rule_version` (`rule_code`,`rule_version`),
  KEY `idx_replenish_rule_status_effective_time` (`status`,`effective_time`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='补货规则配置';

-- review_useful 书评有用记录
CREATE TABLE `review_useful` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `review_id` bigint NOT NULL DEFAULT '0' COMMENT '书评 book_review.id',
  `user_id` bigint NOT NULL DEFAULT '0' COMMENT '点有用的用户 sys_user.id',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '逻辑删除 0 否 1 是',
  `create_by` bigint NULL DEFAULT NULL COMMENT '创建人',
  `update_by` bigint NULL DEFAULT NULL COMMENT '最后修改人',
  `version` int NOT NULL DEFAULT '0' COMMENT '乐观锁版本号',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_review_useful_review_id_user_id` (`review_id`,`user_id`),
  KEY `idx_review_useful_review_id` (`review_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='书评有用记录';

-- sys_user 用户
CREATE TABLE `sys_user` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `username` varchar(40) NOT NULL DEFAULT '' COMMENT '登录账号',
  `password` varchar(100) NOT NULL DEFAULT '' COMMENT 'BCrypt 密码',
  `real_name` varchar(40) NOT NULL DEFAULT '' COMMENT '姓名',
  `student_no` varchar(20) NULL DEFAULT NULL COMMENT '读者编号（读者角色）',
  `phone` varchar(20) NULL DEFAULT NULL COMMENT '手机号',
  `email` varchar(60) NULL DEFAULT NULL COMMENT '邮箱',
  `avatar` varchar(200) NULL DEFAULT NULL COMMENT '头像相对路径',
  `dept_id` bigint NULL DEFAULT NULL COMMENT '所属学院/部门 sys_org.id',
  `role_id` bigint NULL DEFAULT NULL COMMENT '主角色 sys_role.id（菜单与数据范围据此取）',
  `class_name` varchar(50) NULL DEFAULT NULL COMMENT '会员等级',
  `title` varchar(40) NULL DEFAULT NULL COMMENT '岗位 / 职务',
  `credit_score` decimal(5,1) NULL DEFAULT NULL COMMENT '信用分（恶意退货扣减）',
  `fail_count` int NULL DEFAULT NULL COMMENT '连续登录失败次数',
  `lock_time` datetime NULL DEFAULT NULL COMMENT '锁定截止时间，为空表示未锁定',
  `last_login_time` datetime NULL DEFAULT NULL COMMENT '最近登录时间',
  `status` tinyint NOT NULL DEFAULT '0' COMMENT '状态 1正常 0停用',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '逻辑删除 0 否 1 是',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_sys_user_username` (`username`),
  KEY `idx_sys_user_dept_id_status` (`dept_id`,`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='用户';

-- sys_org 组织
CREATE TABLE `sys_org` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `org_name` varchar(50) NOT NULL DEFAULT '' COMMENT '组织名称 如总店/仓储中心',
  `org_code` varchar(30) NULL DEFAULT NULL COMMENT '组织编码',
  `parent_id` bigint NOT NULL DEFAULT '0' COMMENT '上级组织',
  `org_type` varchar(20) NOT NULL DEFAULT '' COMMENT '类型 总部/门店/仓储/采购',
  `leader` varchar(40) NULL DEFAULT NULL COMMENT '负责人',
  `phone` varchar(20) NULL DEFAULT NULL COMMENT '联系电话',
  `sort_no` int NULL DEFAULT NULL COMMENT '排序',
  `status` tinyint NOT NULL DEFAULT '0' COMMENT '状态 1正常 0停用',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '逻辑删除 0 否 1 是',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_sys_org_org_name` (`org_name`),
  KEY `idx_sys_org_parent_id` (`parent_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='组织';

-- sys_role 角色
CREATE TABLE `sys_role` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `role_name` varchar(40) NOT NULL DEFAULT '' COMMENT '角色名称',
  `role_code` varchar(30) NOT NULL DEFAULT '' COMMENT '角色编码 READER/CLERK/KEEPER/BUYER/OPS/ADMIN',
  `data_scope` varchar(20) NULL DEFAULT NULL COMMENT '数据范围 ALL/ORG/SELF',
  `sort_no` int NULL DEFAULT NULL COMMENT '排序',
  `remark` varchar(200) NULL DEFAULT NULL COMMENT '说明',
  `status` tinyint NOT NULL DEFAULT '0' COMMENT '状态 1正常 0停用',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '逻辑删除 0 否 1 是',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_sys_role_role_code` (`role_code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='角色';

-- sys_user_role 用户角色
CREATE TABLE `sys_user_role` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `user_id` bigint NOT NULL DEFAULT '0' COMMENT '用户 sys_user.id',
  `role_id` bigint NOT NULL DEFAULT '0' COMMENT '角色 sys_role.id',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '逻辑删除 0 否 1 是',
  PRIMARY KEY (`id`),
  KEY `idx_sys_user_role_user_id` (`user_id`),
  KEY `idx_sys_user_role_role_id` (`role_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='用户角色';

-- sys_menu 菜单
CREATE TABLE `sys_menu` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `parent_id` bigint NOT NULL DEFAULT '0' COMMENT '上级菜单 0为根',
  `menu_name` varchar(50) NOT NULL DEFAULT '' COMMENT '菜单名称',
  `menu_type` varchar(10) NOT NULL DEFAULT '' COMMENT '类型 DIR目录/MENU菜单/BTN按钮',
  `path` varchar(120) NULL DEFAULT NULL COMMENT '路由地址',
  `component` varchar(120) NULL DEFAULT NULL COMMENT '组件路径',
  `perms` varchar(100) NULL DEFAULT NULL COMMENT '权限标识',
  `icon` varchar(40) NULL DEFAULT NULL COMMENT '图标',
  `sort_no` int NOT NULL DEFAULT '0' COMMENT '排序',
  `visible` tinyint NOT NULL DEFAULT '0' COMMENT '是否可见 1是 0否',
