  `status` varchar(20) NOT NULL DEFAULT '' COMMENT '状态 草稿/已发布/已下线',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '逻辑删除 0 否 1 是',
  PRIMARY KEY (`id`),
  KEY `idx_sys_notice_status` (`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='公告';

-- sys_message 站内消息
CREATE TABLE `sys_message` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `receiver_id` bigint NOT NULL DEFAULT '0' COMMENT '接收人 sys_user.id',
  `title` varchar(120) NULL DEFAULT NULL COMMENT '标题',
  `content` varchar(500) NULL DEFAULT NULL COMMENT '内容',
  `msg_type` varchar(20) NULL DEFAULT NULL COMMENT '类型 订单/退换/库存/审核/系统',
  `biz_type` varchar(30) NULL DEFAULT NULL COMMENT '业务类型 order/return/stock/review',
  `biz_id` bigint NULL DEFAULT NULL COMMENT '业务主键',
  `link_url` varchar(160) NULL DEFAULT NULL COMMENT '跳转路径',
  `read_flag` tinyint NOT NULL DEFAULT '0' COMMENT '是否已读 0未读 1已读',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '逻辑删除 0 否 1 是',
  PRIMARY KEY (`id`),
  KEY `idx_sys_message_receiver_id_read_flag` (`receiver_id`,`read_flag`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='站内消息';

-- sys_oper_log 操作日志
CREATE TABLE `sys_oper_log` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `module` varchar(40) NULL DEFAULT NULL COMMENT '模块',
  `oper_type` varchar(30) NULL DEFAULT NULL COMMENT '操作类型 新增/修改/审核/发货',
  `biz_no` varchar(40) NULL DEFAULT NULL COMMENT '业务编号',
  `content` varchar(500) NULL DEFAULT NULL COMMENT '内容摘要',
  `oper_id` bigint NULL DEFAULT NULL COMMENT '操作人 sys_user.id',
  `oper_name` varchar(40) NULL DEFAULT NULL COMMENT '操作人姓名',
  `oper_time` datetime NULL DEFAULT NULL COMMENT '操作时间',
  `ip` varchar(40) NULL DEFAULT NULL COMMENT 'IP',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '逻辑删除 0 否 1 是',
  PRIMARY KEY (`id`),
  KEY `idx_sys_oper_log_oper_time` (`oper_time`),
  KEY `idx_sys_oper_log_oper_id` (`oper_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='操作日志';



























-- ---------- 回填汇总字段（账实一致） ----------
UPDATE `book` b SET b.stock_qty = COALESCE((SELECT f.after_qty FROM `stock_flow` f WHERE f.book_id = b.id ORDER BY f.id DESC LIMIT 1), 0), b.locked_qty = 0, b.total_sales = (SELECT COALESCE(SUM(oi.item_count),0) FROM `book_order` oi WHERE oi.book_id = b.id AND oi.status IN ('已完成','退换中') AND oi.deleted = 0), b.shortage_count = (SELECT COUNT(*) FROM `replenish_plan` p WHERE p.book_id = b.id AND p.s_stockout >= 40);
UPDATE `book_order` o SET o.status = '退换中' WHERE o.id IN (SELECT r.order_id FROM `book_return` r WHERE r.status IN ('待审核','待寄回','已寄回') AND r.deleted = 0) AND o.status IN ('已签收','已完成');
UPDATE `book_category` c SET c.book_count = (SELECT COUNT(*) FROM `book` b WHERE b.category_id = c.id AND b.deleted = 0);
-- 父分类数量 = 自身 + 子分类
UPDATE `book_category` c SET c.book_count = c.book_count + (SELECT COALESCE(SUM(s.book_count),0) FROM (SELECT * FROM `book_category`) s WHERE s.parent_id = c.id);

