INSERT INTO `sys_notice` (`id`,`title`,`content`,`notice_type`,`publish_time`,`publisher_id`,`status`,`create_time`,`update_time`,`deleted`) VALUES
(1,'关于「双十一」期间发货时效的说明','大促期间订单量激增，仓库拣货时效由 24 小时调整为 48 小时，超 48 小时未更新物流节点的订单会进入异常列表由店员跟进。','通知','2026-09-23 10:00:00',2,'已发布','2026-09-23 10:00:00','2026-09-25 10:00:00',0),
(2,'补货建议规则升级至 v3 的公告','自本月起补货优先级分按近30天销量35%、库存周转25%、在途20%、季节系数10%、近90天缺货10%计算，历史计算留痕不受影响。','规则','2026-09-30 10:00:00',2,'已发布','2026-09-30 10:00:00','2026-10-02 10:00:00',0),
(3,'图书售价与折扣审批口径','售价不得高于定价 1.2 倍；低于定价 70% 的折扣必须经运营管理员审批后生效，未审批的折扣价不允许上架。','规则','2026-10-07 10:00:00',2,'已发布','2026-10-07 10:00:00','2026-10-09 10:00:00',0),
(4,'退换货受理时限提醒','签收后 7 天内可申请退换，超过 15 天不再受理。退回图书须由库管员质检，缺页污损按折扣退款。','通知','2026-10-14 10:00:00',2,'已发布','2026-10-14 10:00:00','2026-10-16 10:00:00',0),
(5,'书评审核与敏感词说明','书评内容不少于 15 字，含联系方式或命中敏感词的内容将自动隐藏并转人工审核，审核人不得审核本人提交的内容。','公告','2026-10-21 10:00:00',2,'已发布','2026-10-21 10:00:00','2026-10-23 10:00:00',0);
