INSERT INTO `book_review` (`id`,`review_no`,`book_id`,`order_id`,`customer_id`,`score`,`title`,`content`,`image_urls`,`useful_count`,`reply_content`,`reply_time`,`status`,`create_time`,`update_time`,`deleted`,`create_by`,`update_by`,`version`) VALUES
(1,'SP260516000001',32,1,3,5,'值得一读','书的质量很好，纸张厚实不反光，排版舒服，读了三天就读完了，内容比预期更有深度。',NULL,12,'感谢您的细致反馈，已把索引问题反馈给出版社。','2026-05-18 21:00:00','已展示','2026-05-16 21:00:00','2026-05-18 21:00:00',0,3,NULL,0),
(2,'SP260518000002',37,3,21,4,'值得一读','作者的行文太克制了，看到一半才明白主角为什么离开，读完回味了很久，值得推荐。','/uploads/seed/review/03.jpg,/uploads/seed/review/04.jpg',1,NULL,NULL,'已展示','2026-05-18 18:02:00','2026-05-18 18:02:00',0,21,NULL,0),
(3,'SP260515000003',32,5,23,3,'适合入门','买给孩子看的，插画很温柔，文字量不大，孩子自己就能读完，睡前读一遍正好。','/uploads/seed/review/01.jpg',24,NULL,NULL,'已隐藏','2026-05-15 07:04:00','2026-05-15 07:04:00',0,23,NULL,0),
(4,'SP260517000004',17,6,24,5,'适合入门','案例很贴近国内实际，不像某些翻译书满篇都是国外的例子，做方案时直接能用上。','/uploads/seed/review/02.jpg,/uploads/seed/review/03.jpg',21,NULL,NULL,'已展示','2026-05-17 18:05:00','2026-05-17 18:05:00',0,24,NULL,0),
(5,'SP260521000005',17,7,25,2,'中规中矩','内容扎实但有点厚，通勤带着不方便。知识点讲解顺序合理，配合代码跑一遍就懂了。',NULL,0,NULL,NULL,'已展示','2026-05-21 17:06:00','2026-05-21 17:06:00',0,25,NULL,0),
(6,'SP260516000006',36,9,27,5,NULL,'整体不错，就是有几页印刷稍微偏淡，不影响阅读，客服也主动联系补了运费券。','/uploads/seed/review/01.jpg,/uploads/seed/review/02.jpg',44,'很抱歉给您带来不便，已为您补发运费券，请注意查收。','2026-05-18 09:08:00','已展示','2026-05-16 09:08:00','2026-05-18 09:08:00',0,27,NULL,0),
(7,'SP260520000007',6,11,29,4,'有点超出预期','读到第三章就被说服了，之前一直用错方法，按书里的思路重新整理后效率明显提升。','/uploads/seed/review/03.jpg',28,NULL,NULL,'已隐藏','2026-05-20 19:10:00','2026-05-20 19:10:00',0,29,NULL,0),
(8,'SP260519000008',34,13,31,5,'有点超出预期','书的质量很好，纸张厚实不反光，排版舒服，读了三天就读完了，内容比预期更有深度。',NULL,11,'很抱歉给您带来不便，已为您补发运费券，请注意查收。','2026-05-21 20:12:00','已展示','2026-05-19 20:12:00','2026-05-21 20:12:00',0,31,NULL,0),
(9,'SP260521000009',17,15,33,5,'有点超出预期','作者的行文太克制了，看到一半才明白主角为什么离开，读完回味了很久，值得推荐。','/uploads/seed/review/03.jpg,/uploads/seed/review/04.jpg',41,NULL,NULL,'已展示','2026-05-21 19:14:00','2026-05-21 19:14:00',0,33,NULL,0),
(10,'SP260523000010',34,16,34,5,'有点超出预期','印刷清晰，图表是全彩的，作为工具书放在手边随时翻。唯一不足是索引做得不够细。',NULL,26,NULL,NULL,'待审核','2026-05-23 21:15:00','2026-05-23 21:15:00',0,34,NULL,0),
(11,'SP260521000011',25,17,35,4,NULL,'买给孩子看的，插画很温柔，文字量不大，孩子自己就能读完，睡前读一遍正好。','/uploads/seed/review/01.jpg',37,NULL,NULL,'已隐藏','2026-05-21 16:16:00','2026-05-21 16:16:00',0,35,NULL,0),
(12,'SP260524000012',30,19,20,3,'适合入门','内容扎实但有点厚，通勤带着不方便。知识点讲解顺序合理，配合代码跑一遍就懂了。',NULL,12,NULL,NULL,'已展示','2026-05-24 12:18:00','2026-05-24 12:18:00',0,20,NULL,0),
(13,'SP260525000013',17,21,22,2,'值得一读','整体不错，就是有几页印刷稍微偏淡，不影响阅读，客服也主动联系补了运费券。','/uploads/seed/review/01.jpg,/uploads/seed/review/02.jpg',8,'谢谢支持，这本书本月还有同系列新书上架，欢迎关注。','2026-05-27 21:20:00','已展示','2026-05-25 21:20:00','2026-05-27 21:20:00',0,22,NULL,0),
(14,'SP260524000014',1,23,24,5,'有点超出预期','读到第三章就被说服了，之前一直用错方法，按书里的思路重新整理后效率明显提升。','/uploads/seed/review/03.jpg',17,NULL,NULL,'已隐藏','2026-05-24 05:22:00','2026-05-24 05:22:00',0,24,NULL,0),
(15,'SP260526000015',18,25,26,4,'装帧与内容都在线','书的质量很好，纸张厚实不反光，排版舒服，读了三天就读完了，内容比预期更有深度。',NULL,46,'很抱歉给您带来不便，已为您补发运费券，请注意查收。','2026-05-28 19:24:00','已展示','2026-05-26 19:24:00','2026-05-28 19:24:00',0,26,NULL,0),
(16,'SP260526000016',3,26,27,3,'装帧与内容都在线','快递很快，包装用了气泡膜没有磕角。内容偏理论，适合有一定基础的读者，入门可能会有点吃力。','/uploads/seed/review/02.jpg',14,NULL,NULL,'已展示','2026-05-26 08:25:00','2026-05-26 08:25:00',0,27,NULL,0),
(17,'SP260529000017',17,27,28,5,NULL,'作者的行文太克制了，看到一半才明白主角为什么离开，读完回味了很久，值得推荐。','/uploads/seed/review/03.jpg,/uploads/seed/review/04.jpg',22,NULL,NULL,'已展示','2026-05-29 09:26:00','2026-05-29 09:26:00',0,28,NULL,0),
