(179,'SP261101000179',18,577,34,4,'中规中矩','整体不错，就是有几页印刷稍微偏淡，不影响阅读，客服也主动联系补了运费券。','/uploads/seed/review/01.jpg,/uploads/seed/review/02.jpg',21,'感谢您的细致反馈，已把索引问题反馈给出版社。','2026-11-03 02:36:00','已展示','2026-11-01 02:36:00','2026-11-03 02:36:00',0,34,NULL,0),
(180,'SP261102000180',34,579,3,3,NULL,'读到第三章就被说服了，之前一直用错方法，按书里的思路重新整理后效率明显提升。','/uploads/seed/review/03.jpg',1,NULL,NULL,'已隐藏','2026-11-02 20:38:00','2026-11-02 20:38:00',0,3,NULL,0),
(181,'SP261102000181',6,581,21,2,'有点超出预期','书的质量很好，纸张厚实不反光，排版舒服，读了三天就读完了，内容比预期更有深度。',NULL,26,'感谢您的细致反馈，已把索引问题反馈给出版社。','2026-11-04 18:40:00','已展示','2026-11-02 18:40:00','2026-11-04 18:40:00',0,21,NULL,0),
(182,'SP261105000182',17,583,23,5,'中规中矩','作者的行文太克制了，看到一半才明白主角为什么离开，读完回味了很久，值得推荐。','/uploads/seed/review/03.jpg,/uploads/seed/review/04.jpg',2,NULL,NULL,'已展示','2026-11-05 13:42:00','2026-11-05 13:42:00',0,23,NULL,0),
(183,'SP261106000183',34,585,25,4,'值得一读','买给孩子看的，插画很温柔，文字量不大，孩子自己就能读完，睡前读一遍正好。','/uploads/seed/review/01.jpg',41,NULL,NULL,'已隐藏','2026-11-06 03:44:00','2026-11-06 03:44:00',0,25,NULL,0),
(184,'SP261103000184',19,586,26,3,'值得一读','案例很贴近国内实际，不像某些翻译书满篇都是国外的例子，做方案时直接能用上。','/uploads/seed/review/02.jpg,/uploads/seed/review/03.jpg',46,NULL,NULL,'已展示','2026-11-03 12:45:00','2026-11-03 12:45:00',0,26,NULL,0),
(185,'SP261103000185',4,587,27,5,'有点超出预期','内容扎实但有点厚，通勤带着不方便。知识点讲解顺序合理，配合代码跑一遍就懂了。',NULL,12,NULL,NULL,'已展示','2026-11-03 06:46:00','2026-11-03 06:46:00',0,27,NULL,0);
